import type {FC} from 'react'

interface TrafficErrorProps {
  error: string
}

export const TrafficError: FC<TrafficErrorProps> = ({error}) => (
  <div className="text-center p-3" data-hpc>
    <div className="msg">
      <p>
        {error.includes('Not Found') || error.includes('Forbidden') || error.includes('push access')
          ? 'Traffic data is only available for private repositories with push access.'
          : 'There was an error fetching the data'}
      </p>
    </div>
  </div>
)

try{ TrafficError.displayName ||= 'TrafficError' } catch {}