/**
 * @fileoverview Shared utilities for fetching and transforming traffic data.
 *
 * This module contains utility functions used across all traffic hooks to reduce
 * code duplication while maintaining focused hook implementations. It handles
 * data transformation and common operations.
 */

import type {
  TrafficDataPoint,
  RawReferringSiteItem,
  RawPopularContentItem,
  SiteDataItem,
  RawReferringPathItem,
} from './traffic-types'

/**
 * Raw traffic count structure from API before date transformation.
 *
 * @interface RawTrafficCount
 * @property {number} bucket - Time bucket identifier
 * @property {number} timestamp - Unix timestamp for this data point
 * @property {number} total - Total count for this time period
 * @property {number} unique - Unique count for this time period
 */
interface RawTrafficCount {
  bucket: number
  timestamp: number
  total: number
  unique: number
}

/**
 * Transforms raw traffic counts from API into structured traffic data points.
 *
 * Converts Unix timestamps to Date objects and ensures consistent data structure
 * across all traffic hooks.
 *
 * @param rawCounts - Array of raw traffic counts from the API
 * @returns Array of transformed traffic data points with Date objects
 *
 * @example
 * ```typescript
 * const rawData = [{bucket: 1, timestamp: 1640995200000, total: 100, unique: 50}]
 * const transformed = transformTrafficCounts(rawData)
 * // Result: [{bucket: 1, date: Date, total: 100, unique: 50}]
 * ```
 */
export function transformTrafficCounts(rawCounts: RawTrafficCount[]): TrafficDataPoint[] {
  return rawCounts.map(count => ({
    bucket: count.bucket,
    date: new Date(count.timestamp),
    total: count.total,
    unique: count.unique,
  }))
}

/**
 * Transforms raw referring sites data to site data items
 */
export function transformReferringSites(rawData: RawReferringSiteItem[]): SiteDataItem[] {
  return rawData.map((item, index) => ({
    id: item.referrer || `unknown-${index}`,
    site: item.referrer || 'Unknown',
    views: item.count || 0,
    uniqueVisitors: item.uniques || 0,
    referrerPathsAllowed: item.referrer_paths_allowed,
  }))
}

/**
 * Transforms raw popular content data to site data items
 */
export function transformPopularContent(rawData: RawPopularContentItem[]): SiteDataItem[] {
  return rawData.map((item, index) => ({
    id: item.path || `unknown-${index}`,
    site: item.title || item.path || 'Unknown', // Use title for display, fallback to path then Unknown
    path: item.path, // Keep the original path for linking
    title: item.title, // Keep the original title
    views: item.count || 0,
    uniqueVisitors: item.uniques || 0,
  }))
}

/**
 * Transforms raw referring paths data to site data items
 */
export function transformReferringPaths(rawData: RawReferringPathItem[]): SiteDataItem[] {
  return rawData.map((item, index) => ({
    id: item.path || `unknown-${index}`,
    site: item.path || 'Unknown',
    views: item.count || 0,
    uniqueVisitors: item.uniques || 0,
  }))
}
