import {usePopularContent} from '../../hooks/use-popular-content'
import {useRepoContext} from '../../hooks/use-repo-context'
import {GenericTrafficTable} from './GenericTrafficTable'
import type {TrafficDataItem} from '../TrafficDataTable'

export function PopularContentTable() {
  const {owner, repo} = useRepoContext()
  const fullDataUrl = `/${owner}/${repo}/graphs/traffic-new/popular-content`

  const {data, isLoading, error} = usePopularContent({
    dataUrl: fullDataUrl,
  })

  const transformedData =
    data?.map(
      (item, index) =>
        ({
          ...item,
          id: index.toString(),
        }) as TrafficDataItem,
    ) ?? null

  return (
    <GenericTrafficTable
      config={{
        title: 'Popular content',
        emptyMessage: 'No popular content data available for this period',
        ariaLabelledBy: 'popular-content',
        firstColumnHeader: 'Content',
        linkType: 'page',
      }}
      trafficData={{data: transformedData, isLoading, error: error ?? null}}
    />
  )
}

try{ PopularContentTable.displayName ||= 'PopularContentTable' } catch {}