import {useTrafficData} from './use-traffic-data'
import {transformTrafficData} from '../utils/transform-traffic-data'
import {useMemo} from 'react'

interface UseTrafficChartOptions {
  dataUrl: string
  per: 'day' | 'week'
  enabled?: boolean
  includeTotal?: boolean
  includeUnique?: boolean
}

/**
 * Hook that wraps useTrafficData (fetcher) and transformTrafficData (formatter)
 * Provides chartData, isLoading, error for rendering traffic charts from an API.
 */
export function useTrafficChart({
  dataUrl,
  per,
  enabled = true,
  includeTotal = true,
  includeUnique = true,
}: UseTrafficChartOptions) {
  const {data: realData, isLoading, error} = useTrafficData({dataUrl, period: per, enabled})

  const transformedData = useMemo(() => {
    if (!realData) return null

    return transformTrafficData(realData, {period: per, includeTotal, includeUnique})
  }, [realData, per, includeTotal, includeUnique])

  return {
    chartData: transformedData,
    isLoading,
    error,
  }
}
