import {useMemo} from 'react'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {transformPopularContent} from './traffic-utils'
import type {RawPopularContentItem, SiteDataItem} from './traffic-types'

/**
 * Defines the input options for the hook
 */
interface UsePopularContentOptions {
  dataUrl: string // The URL to fetch popular content data from
}

/**
 * Hook return type for popular content data
 */
interface UsePopularContentResult {
  data: SiteDataItem[] | null
  error?: string
  isLoading: boolean
}

/**
 * Hook that fetches popular content data from a given URL and transforms it into a usable format.
 */
export function usePopularContent({dataUrl}: UsePopularContentOptions): UsePopularContentResult {
  const fetchPopularContent = async (): Promise<RawPopularContentItem[]> => {
    const response = await verifiedFetchJSON(dataUrl)

    if (!response.ok) {
      throw new Error(`Failed to fetch popular content data: ${response.statusText}`)
    }

    return await response.json()
  }

  const {
    data: rawData,
    error: queryError,
    isLoading: queryIsLoading,
  } = useQuery({
    queryKey: ['popular-content', dataUrl],
    queryFn: fetchPopularContent,
    refetchOnWindowFocus: false,
    staleTime: 60000, // 1 minute
    gcTime: 300000, // 5 minutes
  })

  const data = useMemo(() => {
    if (!rawData) return null
    return transformPopularContent(rawData)
  }, [rawData])

  return {
    data,
    error: queryError?.message,
    isLoading: queryIsLoading,
  }
}
