import {mainQuery} from '@github-ui/react-core/future/main-query'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {reposTrafficAppBuilder} from '../config/app-builder'

export type TrafficResponse = {
  graphDataPath: string
  referringSites?: Array<{site: string; views: number}>
}

const useExistingUrl = isFeatureEnabled('repos_insights_remove_new_url')

export const trafficRoute = reposTrafficAppBuilder.createQueryRouteConfig('trafficRoute', {
  path: useExistingUrl ? '/:owner/:repo/graphs/traffic' : '/:owner/:repo/graphs/traffic-new',
  queries: [mainQuery<TrafficResponse>()],
})
